files.apps.js:
// 지금 앞에 떠 있는(사용 중인) 프로그램 알아내기 (Windows)
// - 숨겨진 PowerShell 하나를 계속 띄워 두고 2초마다 맨 앞 창의 프로그램 경로를 받는다.
// - 창을 띄우거나 포커스를 건드리지 않는다 (게임 보호). 프로세스는 '이름 조회' 권한으로만 연다.
// - 이 프로그램이 꺼지면 PowerShell도 스스로 끝난다.
const path = require('path');
const { spawn } = require('child_process');

const PS = (parentPid) => `
$ErrorActionPreference = 'SilentlyContinue'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
Add-Type @"
using System; using System.Text; using System.Runtime.InteropServices;
public static class PcbFg {
  [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
  [DllImport("kernel32.dll")] static extern IntPtr OpenProcess(uint a, bool i, uint pid);
  [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
  [DllImport("kernel32.dll", CharSet=CharSet.Unicode)] static extern bool QueryFullProcessImageName(IntPtr h, uint f, StringBuilder s, ref uint n);
  public static uint Pid; public static string Title;
  public static string Now() {
    Pid = 0; Title = "";
    IntPtr w = GetForegroundWindow(); if (w == IntPtr.Zero) return "";
    uint pid; GetWindowThreadProcessId(w, out pid); Pid = pid; if (pid == 0) return "";
    var t = new StringBuilder(256); GetWindowText(w, t, 256); Title = t.ToString();
    IntPtr h = OpenProcess(0x1000, false, pid); if (h == IntPtr.Zero) return "";
    try { var s = new StringBuilder(1024); uint n = 1024; return QueryFullProcessImageName(h, 0, s, ref n) ? s.ToString() : ""; }
    finally { CloseHandle(h); }
  }
}
"@
$desc = @{}
while ($true) {
  if (-not (Get-Process -Id ${parentPid})) { exit }
  $p = [PcbFg]::Now()
  $name = ''
  if ([PcbFg]::Pid -ne 0) { try { $name = [System.Diagnostics.Process]::GetProcessById([PcbFg]::Pid).ProcessName } catch {} }
  if ($p -and -not $desc.ContainsKey($p)) {
    $d = ''
    try { $d = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($p).FileDescription } catch {}
    $desc[$p] = "$d".Trim()
  }
  $line = "$name\`t$p\`t" + $desc[$p] + "\`t" + ([PcbFg]::Title -replace '[\\t\\r\\n]', ' ')
  [Console]::Out.WriteLine($line)
  [Console]::Out.Flush()
  Start-Sleep -Seconds 2
}
`;

// 실행 파일 정보로 보기 좋은 이름 만들기
const FRIENDLY = {
  explorer: 'Windows 탐색기 · 바탕화면',
  applicationframehost: '', // UWP 앱: 창 제목 사용
  javaw: '', java: '',      // 마인크래프트 등: 창 제목 사용
};
const GENERIC = /^(electron|java\(tm\).*|openjdk.*|application frame host|)$/i;
function labelOf({ name, file, desc, title }, selfExe) {
  if (!name && !file) return null;
  if (file && selfExe && file.toLowerCase() === selfExe.toLowerCase()) return 'PC방 프로그램 (주문·채팅)';
  const key = (name || path.basename(file || '', '.exe')).toLowerCase();
  if (key === 'lockapp' || key === 'idle') return null;
  if (key in FRIENDLY && FRIENDLY[key]) return FRIENDLY[key];
  if (key in FRIENDLY || (desc && GENERIC.test(desc))) {
    // 창 제목의 앞부분만 (버전 숫자, " - " 뒤 내용은 뺀다)
    const t = String(title || '').split(/ [-–—|] /)[0].replace(/\s*[\d.]+\s*$/, '').trim();
    if (t) return t.slice(0, 40);
  }
  return (desc || name || path.basename(file, '.exe')).slice(0, 40);
}

function createAppWatcher(log = () => {}) {
  let current = null;   // 지금 앞에 있는 프로그램 이름 (모르면 null)
  let child = null;
  let stopped = false;
  let lastLine = 0;
  let fails = 0;

  function start() {
    if (process.platform !== 'win32' || stopped) return;
    const script = PS(process.pid);
    const enc = Buffer.from(script, 'utf16le').toString('base64');
    try {
      child = spawn('powershell.exe', ['-NoLogo', '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-EncodedCommand', enc], {
        windowsHide: true, stdio: ['ignore', 'pipe', 'ignore'],
      });
    } catch (e) { log('apps spawn', e.message); return retry(); }
    let buf = '';
    child.stdout.setEncoding('utf8');
    child.stdout.on('data', (chunk) => {
      buf += chunk;
      let i;
      while ((i = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, i).replace(/\r$/, ''); buf = buf.slice(i + 1);
        const [name, file, desc, title] = line.split('\t');
        current = labelOf({ name, file, desc, title }, process.execPath);
        lastLine = Date.now(); fails = 0;
      }
    });
    child.on('exit', () => { child = null; current = null; retry(); });
    child.on('error', () => {});
  }
  function retry() {
    if (stopped) return;
    fails += 1;
    setTimeout(start, Math.min(5 * 60_000, 5000 * fails));
  }
  start();
  return {
    // 6초 넘게 소식이 없으면 모르는 것으로 본다
    current: () => (Date.now() - lastLine < 6000 ? current : null),
    stop() { stopped = true; try { child?.kill(); } catch {} },
  };
}

module.exports = { createAppWatcher, labelOf };

