  [/초코|초콜릿/, '🍫', ['#e7d3c1', '#78350f']],
  [/빵|샌드위치|토스트/, '🥪', ['#fef3c7', '#a16207']],
  [/에너지|핫식스|레드불|몬스터/, '⚡', ['#d9f99d', '#15803d']],
  [/맥주|음료/, '🥤', ['#ddd6fe', '#6d28d9']],
];
function menuArt(name) {
  for (const [re, emoji, colors] of MENU_ART) if (re.test(name || '')) return { emoji, colors };
  return { emoji: '🍽️', colors: ['#e0e7ff', '#4f46e5'] };
}

// 버전 표시: "v1.2.4 · 10/31 22:05 업데이트"
function verText(s) {
  let t = 'v' + (s.version || '?');
  if (s.updated) {
    const d = new Date(s.updated), p = (n) => String(n).padStart(2, '0');
    t += ` · ${d.getMonth() + 1}/${d.getDate()} ${p(d.getHours())}:${p(d.getMinutes())} 업데이트`;
  }
  return t;
}

