// 강제 종료 감시 (Windows 작업 스케줄러) - 1.7.0 강화판
// 작업 관리자에서 손님 프로그램과 감시 프로그램을 한꺼번에 끄면 둘 다 다시 켜 줄 수 없다.
// 그래서 윈도우 작업 스케줄러가 감시 스크립트(guard.vbs)를 계속 돌린다.
//
// 감시 스크립트 (guard.vbs)
// - 한 번 켜지면 계속 돌면서 2초마다 손님 프로그램이 살아 있는지 본다. (예전: 1분마다 + 45초 대기)
//   스크립트가 꺼져도 작업 스케줄러가 1분 안에 다시 켜고, 손님 프로그램도 20초마다 확인해서 다시 켠다.
// - 손님 프로그램이 정상 종료(관리자 PIN, 업데이트, 윈도우 종료)하면 quit-ok 파일에 그 프로세스 번호를 남긴다.
//   번호가 없는데 프로그램이 사라지면 강제 종료로 보고 15초 안내 뒤 PC를 강제로 끈다 (shutdown /f /t 0, 취소 불가).
// - 안내 중에 스크립트를 꺼도 'tripped' 기록이 남아 있어서, 다시 켜진 스크립트가 바로 PC를 끈다.
// - 프로그램을 '일시 중지'(리소스 모니터 등)해서 멈춰 두면 90초 뒤 강제 종료와 같이 처리한다.
// - 손님 프로그램이 안 켜져 있으면(시작 프로그램을 꺼 둔 경우 등) 감시 스크립트가 직접 켠다.
//   관리자 PIN으로 끈 경우에는 다음 로그인 전까지 켜지 않는다.
// - 정전, 로그오프, 윈도우 종료 뒤에 남은 기록은 무시한다.
//
// 작업 스케줄러 작업 (PCBangGuard)
// - 노트북 배터리 상태에서도 돌고, 실행 시간 제한이 없고, 목록에서 숨겨진다.
// - 누가 작업을 지우거나 '사용 안 함'으로 바꾸면 손님 프로그램이 다시 만들고 관리자에게 알린다.
const fs = require('fs');
const path = require('path');
const os = require('os');
const { execFile } = require('child_process');

const TASK = 'PCBangGuard';
const MSG_KILLED = 'PC방 프로그램이 강제로 종료되었습니다. 약속대로 15초 뒤 이 PC가 꺼집니다.';
const MSG_FROZEN = 'PC방 프로그램이 일시 중지(멈춤)되었습니다. 약속대로 15초 뒤 이 PC가 꺼집니다.';

const xmlEsc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;' }[c]));

function vbs(f) {
  const q = (s) => String(s).replace(/"/g, '""');
  return `' PC방 강제 종료 감시 (자동 생성 파일 - 손님 프로그램이 켜질 때마다 다시 만든다)
Option Explicit
On Error Resume Next
Dim fso, sh, wmi
Set fso = CreateObject("Scripting.FileSystemObject")
Set sh = CreateObject("WScript.Shell")
Set wmi = GetObject("winmgmts:\\\\.\\root\\cimv2")
Const RUN_FILE = "${q(f.run)}"
Const QUIT_FILE = "${q(f.quit)}"
Const ALIVE_FILE = "${q(f.alive)}"
Const TRIP_FILE = "${q(f.trip)}"
Const LOG_FILE = "${q(f.log)}"
Const CFG_FILE = "${q(f.cfg)}"
Const EXE_PATH = "${q(f.exe)}"
Const EXE_NAME = "${q(f.exeName)}"
Const MSG_KILLED = "${q(MSG_KILLED)}"
Const MSG_FROZEN = "${q(MSG_FROZEN)}"

Function WmiDate(v)
  On Error Resume Next
  Dim d
  WmiDate = Empty
  If IsNull(v) Or IsEmpty(v) Then Exit Function
  Set d = CreateObject("WbemScripting.SWbemDateTime")
  d.Value = v
  WmiDate = d.GetVarDate(True)
  If Err.Number <> 0 Then WmiDate = Empty: Err.Clear
End Function

Function FileTime(p)
  On Error Resume Next
  FileTime = Empty
  If fso.FileExists(p) Then FileTime = fso.GetFile(p).DateLastModified
  If Err.Number <> 0 Then FileTime = Empty: Err.Clear
End Function

' 파일 첫 줄의 단어들 (예: "1234 pin")
Function ReadWords(p)
  On Error Resume Next
  Dim f, t
  ReadWords = Array("0", "")
  If Not fso.FileExists(p) Then Exit Function
  Set f = fso.OpenTextFile(p, 1)
  t = Trim(f.ReadLine)
  f.Close
  If Err.Number <> 0 Then Err.Clear: Exit Function
  t = Split(t & " ", " ")
  ReadWords = Array(t(0), t(1))
End Function

Function ReadPid(p)
  Dim w
  ReadPid = 0
  w = ReadWords(p)
  If IsNumeric(w(0)) Then ReadPid = CLng(w(0))
End Function

' 그 번호의 손님 프로그램이 살아 있는지 (같은 번호를 다른 프로그램이 다시 쓰는 경우도 걸러 낸다)
Function PidAlive(p)
  On Error Resume Next
  Dim procs, n
  PidAlive = False
  If p <= 0 Then Exit Function
  Err.Clear
  Set procs = wmi.ExecQuery("SELECT ProcessId FROM Win32_Process WHERE ProcessId = " & p & " AND Name = '${q(f.exeName.replace(/'/g, "''"))}'")
  n = procs.Count
  If Err.Number <> 0 Then Err.Clear: PidAlive = True: Exit Function ' 확인이 안 되면 살아 있는 것으로 (잘못 끄지 않게)
  PidAlive = (n > 0)
End Function

Function HasExplorer()
  On Error Resume Next
  Dim procs, n
  HasExplorer = True
  Set procs = wmi.ExecQuery("SELECT ProcessId FROM Win32_Process WHERE Name = 'explorer.exe'")
  n = procs.Count
  If Err.Number <> 0 Then Err.Clear: Exit Function
  HasExplorer = (n > 0)
End Function

Function BootTime()
  On Error Resume Next
  Dim os
  BootTime = Empty
  For Each os In wmi.ExecQuery("SELECT LastBootUpTime FROM Win32_OperatingSystem")
    BootTime = WmiDate(os.LastBootUpTime)
  Next
End Function

' 이 사용자가 로그인한 시각 (이 사용자의 sihost.exe / explorer.exe 중 가장 먼저 켜진 것)
Function LogonTime()
  On Error Resume Next
  Dim p, d, u, dm, myName, best
  best = Empty
  myName = LCase(sh.ExpandEnvironmentStrings("%USERNAME%"))
  For Each p In wmi.ExecQuery("SELECT * FROM Win32_Process WHERE Name = 'sihost.exe' OR Name = 'explorer.exe'")
    u = "": dm = ""
    If p.GetOwner(u, dm) = 0 Then
      If LCase(u) = myName Then
        d = WmiDate(p.CreationDate)
        If Not IsEmpty(d) Then
          If IsEmpty(best) Then
            best = d
          ElseIf d < best Then
            best = d
          End If
        End If
      End If
    End If
  Next
  LogonTime = best
End Function

Function Stamp()
  Dim n
  n = Now
  Stamp = Year(n) & "-" & Right("0" & Month(n), 2) & "-" & Right("0" & Day(n), 2) & " " & Right("0" & Hour(n), 2) & ":" & Right("0" & Minute(n), 2) & ":" & Right("0" & Second(n), 2)
End Function

Sub WriteText(p, t, mode)
  On Error Resume Next
  Dim f
  Set f = fso.OpenTextFile(p, mode, True)
  f.WriteLine t
  f.Close
  Err.Clear
End Sub

Sub DelFile(p)
  On Error Resume Next
  If fso.FileExists(p) Then fso.DeleteFile p, True
  Err.Clear
End Sub

' PC 끄기. 끄기 시작하기 전에 기록을 남겨서, 이 스크립트를 꺼도 다시 켜진 스크립트가 바로 끈다.
Sub TurnOff(reason, msg, warn)
  On Error Resume Next
  Dim t0
  WriteText TRIP_FILE, Stamp() & " " & reason, 2
  WriteText LOG_FILE, Stamp() & " " & reason, 8
  DelFile RUN_FILE
  If warn Then
    sh.Run "shutdown /s /f /t 15 /c """ & msg & """", 0, False
    t0 = Now
    sh.Popup msg, 15, "PC방 안내", 48 + 4096
    Do While DateDiff("s", t0, Now) < 15
      WScript.Sleep 500
    Loop
  End If
  ' 'shutdown /a' 로 취소해도 소용없게 계속 끈다
  Do
    sh.Run "shutdown /s /f /t 0", 0, False
    WScript.Sleep 10000
  Loop
End Sub

' ---------- 시작 ----------
Dim since, boot, logon, t, pid, knownPid, lastLoop, lastBeat, rt, gap, notRunSince, launches, tick, w
boot = BootTime()
logon = LogonTime()
If IsEmpty(logon) Then logon = Now ' 로그인 시각을 모르면 지금 이전 기록은 모두 지난 것으로 본다
since = logon
If Not IsEmpty(boot) Then
  If boot > since Then since = boot
End If

' 안내 중에 감시 스크립트를 끈 경우: 이번 로그인에서 생긴 기록이면 바로 끈다
t = FileTime(TRIP_FILE)
If Not IsEmpty(t) Then
  If t > since Then TurnOff "tripped-again", MSG_KILLED, False
  DelFile TRIP_FILE
End If

knownPid = 0
lastBeat = Now
t = FileTime(RUN_FILE)
If Not IsEmpty(t) Then
  pid = ReadPid(RUN_FILE)
  If t <= since Then
    DelFile RUN_FILE ' 전원/로그오프 전에 남은 기록
  ElseIf PidAlive(pid) Then
    knownPid = pid
  ElseIf ReadPid(QUIT_FILE) = pid Then
    DelFile RUN_FILE ' 정상 종료
  ElseIf HasExplorer() Then
    TurnOff "killed", MSG_KILLED, True ' 감시 스크립트가 꺼진 사이에 강제 종료됨
  End If
End If

' ---------- 감시 ----------
lastLoop = Now
notRunSince = Now
launches = 0
tick = 0
Do
  WScript.Sleep 2000
  tick = tick + 1
  If tick Mod 3 = 0 Then WriteText ALIVE_FILE, Stamp(), 2 ' 손님 프로그램이 감시 스크립트가 살아 있는지 확인하는 용도

  ' 절전/최대 절전에서 깨어난 경우: 그동안의 공백은 멈춤으로 보지 않는다
  gap = DateDiff("s", lastLoop, Now)
  lastLoop = Now
  If gap > 20 Or gap < 0 Then lastBeat = Now

  If knownPid > 0 Then
    If Not PidAlive(knownPid) Then
      WScript.Sleep 3000 ' 정상 종료 기록을 쓸 시간을 준다
      If ReadPid(QUIT_FILE) = knownPid Then
        knownPid = 0
        notRunSince = Now
      ElseIf Not HasExplorer() Then
        WScript.Quit ' 로그오프/윈도우 종료 중
      Else
        TurnOff "killed", MSG_KILLED, True
      End If
    Else
      rt = FileTime(RUN_FILE)
      If Not IsEmpty(rt) Then
        If rt > lastBeat Then lastBeat = rt
      End If
      If DateDiff("s", lastBeat, Now) > 90 Then TurnOff "frozen", MSG_FROZEN, True
    End If
  End If

  If knownPid = 0 Then
    pid = ReadPid(RUN_FILE)
    If pid > 0 Then
      If PidAlive(pid) Then
        knownPid = pid
        lastBeat = Now
        launches = 0
      End If
    End If
  End If

  ' 손님 프로그램이 안 켜져 있으면 켠다 (관리자 PIN으로 끈 경우는 제외)
  If knownPid = 0 Then
    If DateDiff("s", notRunSince, Now) >= 60 And launches < 3 Then
      notRunSince = Now
      If fso.FileExists(CFG_FILE) And fso.FileExists(EXE_PATH) Then
        w = ReadWords(QUIT_FILE)
        t = FileTime(QUIT_FILE)
        If w(1) = "pin" And Not IsEmpty(t) Then
          If t <= since Then w(1) = ""
        End If
        If w(1) <> "pin" Then
          launches = launches + 1
          sh.Run """" & EXE_PATH & """", 1, False
        End If
      End If
    End If
  Else
    notRunSince = Now
  End If
Loop
`;
}

function taskXml(script) {
  const user = process.env.USERDOMAIN ? `${process.env.USERDOMAIN}\\${process.env.USERNAME}` : (process.env.USERNAME || os.userInfo().username);
  return `<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo>
    <Description>PC방 손님 프로그램 강제 종료 감시</Description>
  </RegistrationInfo>
  <Triggers>
    <TimeTrigger>
      <Repetition>
        <Interval>PT1M</Interval>
        <StopAtDurationEnd>false</StopAtDurationEnd>
      </Repetition>
      <StartBoundary>2020-01-01T00:00:00</StartBoundary>
      <Enabled>true</Enabled>
    </TimeTrigger>
  </Triggers>
  <Principals>
    <Principal id="Author">
      <UserId>${xmlEsc(user)}</UserId>
      <LogonType>InteractiveToken</LogonType>
      <RunLevel>LeastPrivilege</RunLevel>
    </Principal>
  </Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>
    <AllowHardTerminate>true</AllowHardTerminate>
    <StartWhenAvailable>true</StartWhenAvailable>
    <RunOnlyIfNetworkAvailable>false</RunOnlyIfNetworkAvailable>
    <IdleSettings>
      <StopOnIdleEnd>false</StopOnIdleEnd>
      <RestartOnIdle>false</RestartOnIdle>
    </IdleSettings>
    <AllowStartOnDemand>true</AllowStartOnDemand>
    <Enabled>true</Enabled>
    <Hidden>true</Hidden>
    <RunOnlyIfIdle>false</RunOnlyIfIdle>
    <WakeToRun>false</WakeToRun>
    <ExecutionTimeLimit>PT0S</ExecutionTimeLimit>
    <Priority>7</Priority>
  </Settings>
  <Actions Context="Author">
    <Exec>
      <Command>wscript.exe</Command>
      <Arguments>//Nologo "${xmlEsc(script)}"</Arguments>
    </Exec>
  </Actions>
</Task>
`;
}

const run = (cmd, args) => new Promise((resolve) => {
  execFile(cmd, args, { windowsHide: true }, (err, stdout) => resolve({ err, out: String(stdout || '') }));
});

// 작업 관리자 막기 (이 Windows 계정만). 관리자 PIN으로 프로그램을 끄면 다시 풀린다.
const TM_KEY = 'HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Policies\\System';
function setTaskMgrBlock(on, log = () => {}) {
  if (process.platform !== 'win32') return Promise.resolve();
  const args = on ? ['add', TM_KEY, '/v', 'DisableTaskMgr', '/t', 'REG_DWORD', '/d', '1', '/f'] : ['delete', TM_KEY, '/v', 'DisableTaskMgr', '/f'];
  return run('reg', args).then(({ err }) => { if (err && on) log('작업 관리자 막기 실패: ' + err.message); });
}

// opts: { log, onTamper(text) }
function setupGuard(dataDir, opts = {}) {
  const log = opts.log || (() => {});
  const onTamper = opts.onTamper || (() => {});
  if (process.platform !== 'win32') return { beat() {}, stop() {} };
  const f = {
    run: path.join(dataDir, 'running'),
    quit: path.join(dataDir, 'quit-ok'),
    alive: path.join(dataDir, 'guard-alive'),
    trip: path.join(dataDir, 'tripped'),
    log: path.join(dataDir, 'forced.log'),
    cfg: path.join(dataDir, 'config.json'),
    exe: process.env.PORTABLE_EXECUTABLE_FILE || process.execPath,
    exeName: path.basename(process.execPath),
  };
  const script = path.join(dataDir, 'guard.vbs');
  const xmlFile = path.join(dataDir, 'guard-task.xml');
  let stopped = false;

  const beat = () => { if (!stopped) try { fs.writeFileSync(f.run, String(process.pid)); } catch {} };
  try {
    fs.writeFileSync(script, '﻿' + vbs(f).replace(/\n/g, '\r\n'), 'utf16le'); // 한글이 깨지지 않게 UTF-16
    fs.writeFileSync(xmlFile, '﻿' + taskXml(script).replace(/\n/g, '\r\n'), 'utf16le');
  } catch (e) { log('guard 스크립트 저장 실패: ' + e.message); }

  async function register() {
    let r = await run('schtasks', ['/create', '/f', '/tn', TASK, '/xml', xmlFile]);
    if (r.err) {
      log('guard 작업 등록(XML) 실패, 기본 방식으로 등록: ' + r.err.message);
      r = await run('schtasks', ['/create', '/f', '/tn', TASK, '/sc', 'minute', '/mo', '1', '/tr', `wscript.exe //Nologo "${script}"`]);
      if (r.err) log('guard 작업 등록 실패: ' + r.err.message);
    }
    return !r.err;
  }
  // 예전 버전의 감시 스크립트가 돌고 있을 수 있으니 바로 새 스크립트로 시작한다
  async function startNow() { await run('schtasks', ['/end', '/tn', TASK]); await run('schtasks', ['/run', '/tn', TASK]); }

  // 감시 스크립트가 살아 있는지 20초마다 확인. 작업이 지워지거나 꺼져 있으면 다시 만들고 알린다.
  let checking = false;
  async function check() {
    if (stopped || checking) return;
    checking = true;
    try {
      let t = 0;
      try { t = fs.statSync(f.alive).mtimeMs; } catch {}
      if (Date.now() - t > 20_000) {
        const q = await run('schtasks', ['/query', '/tn', TASK, '/xml']);
        let why = null;
        if (q.err) why = '감시 작업이 지워져 있었어요';
        else if (/<Enabled>\s*false\s*<\/Enabled>/i.test(q.out.replace(/<Triggers>[\s\S]*?<\/Triggers>/i, ''))) why = '감시 작업이 꺼져(사용 안 함) 있었어요';
        else if (/<Triggers>[\s\S]*<Enabled>\s*false/i.test(q.out)) why = '감시 작업의 실행 조건이 꺼져 있었어요';
        if (why) { await register(); if (!stopped) onTamper(why); }
        if (!stopped) await run('schtasks', ['/run', '/tn', TASK]);
      }
    } catch (e) { log('guard 확인 실패: ' + e.message); }
    checking = false;
  }

  beat();
  const beatTimer = setInterval(beat, 5_000);
  let checkTimer = null;
  register().then(async (ok) => {
    if (stopped) return;
    if (ok) await startNow();
    checkTimer = setInterval(check, 20_000);
  });
  return {
    beat,
    // 정상 종료: quit-ok를 먼저 쓴 다음(main.js allowQuit) 감시 대상에서 빠진다
    stop() {
      stopped = true;
      clearInterval(beatTimer); clearInterval(checkTimer);
      try { fs.rmSync(f.run, { force: true }); } catch {}
    },
  };
}

// 감시 스크립트가 PC를 끈 기록 (다음에 켜졌을 때 관리자에게 알리고 지운다)
function takeForcedLog(dataDir) {
  const file = path.join(dataDir, 'forced.log');
  try {
    const text = fs.readFileSync(file, 'latin1'); // VBS가 ANSI로 쓴다 (숫자/영문만)
    fs.rmSync(file, { force: true });
    return parseForced(text);
  } catch { return []; }
}
function parseForced(text) {
  return String(text).split(/\r?\n/).map((l) => l.trim()).filter(Boolean).map((l) => {
    const m = l.match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2}) (\S+)/);
    if (!m) return null;
    return { at: new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +m[6]), reason: m[7] };
  }).filter(Boolean);
}

// 빠른 자동 시작
// 윈도우는 '시작 프로그램'(레지스트리 Run)을 로그인 뒤 일부러 늦게 실행한다. 그래서
// 1) 로그인하자마자 실행되는 작업 스케줄러 작업(PCBangStart)을 등록하고 (권한이 없으면 건너뜀)
// 2) 이 사용자의 시작 프로그램 지연(StartupDelayInMSec)을 0으로 바꾼다.
// 두 방법으로 동시에 켜져도 프로그램은 하나만 실행된다.
function setupFastStart(log = () => {}) {
  if (process.platform !== 'win32') return;
  const exe = process.execPath;
  execFile('schtasks', ['/create', '/f', '/tn', 'PCBangStart', '/sc', 'onlogon', '/rl', 'limited', '/tr', `"${exe}"`],
    { windowsHide: true }, (err) => { if (err) log('빠른 시작 작업 등록 실패(권한 부족일 수 있음): ' + err.message); });
  execFile('reg', ['add', 'HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Serialize',
    '/v', 'StartupDelayInMSec', '/t', 'REG_DWORD', '/d', '0', '/f'], { windowsHide: true }, () => {});
}

module.exports = { setupGuard, setupFastStart, setTaskMgrBlock, takeForcedLog, parseForced, _vbs: vbs, _taskXml: taskXml };

