// PC방 손님 프로그램 (Windows)
// - 잠금 화면, 남은 시간 계산, 화면 전송, 메뉴 주문, 채팅
// - 남은 시간은 이 PC가 직접 계산하고 Supabase에 기록한다. 관리자 명령은 commands 테이블로 받는다.
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const { exec, spawn } = require('child_process');
const { app, BrowserWindow, ipcMain, desktopCapturer, screen, globalShortcut, safeStorage, powerMonitor } = require('electron');
const { createClient } = require('@supabase/supabase-js');
const { createUpdater } = require('./updater');
const { setupGuard, setupFastStart, setTaskMgrBlock, takeForcedLog } = require('./guard');
const { createUsage } = require('./usage');
const { createAppWatcher } = require('./apps');
const CODE_VERSION = require('./version.json').version;
const CODE_DATE = require('./version.json').date || null;

if (!app.requestSingleInstanceLock()) app.exit(0);
// 예상 못 한 오류가 나도 손님 화면에 오류 창을 띄우지 않고 기록만 남긴다 (프로그램은 계속 동작)
process.on('uncaughtException', (e) => {
  console.error('uncaught', e);
  try { fs.appendFileSync(path.join(process.env.PCBANG_DATA_DIR || app.getPath('userData'), 'error.log'), `${new Date().toISOString()} ${e?.stack || e}\n`); } catch {}
});

const DATA_DIR = process.env.PCBANG_DATA_DIR || app.getPath('userData');
const CONFIG_FILE = path.join(DATA_DIR, 'config.json');
const STATE_FILE = path.join(DATA_DIR, 'state.json');
const QUIT_FLAG = path.join(DATA_DIR, 'quit-ok');
const CONTROL_CHANNEL = 'pcbang-control';
try { fs.mkdirSync(DATA_DIR, { recursive: true }); } catch {}
// 사용 기록 (PC 켜짐/꺼짐, 실제 사용 시간, 프로그램별 시간)
// 강제 종료 감시가 지난번에 PC를 끈 기록 (관리자에게 알리고, 사용 기록에 '강제 종료'로 남긴다)
const forcedEvents = process.platform === 'win32' ? takeForcedLog(DATA_DIR) : [];
const usage = createUsage({ dataDir: DATA_DIR, log: console.log, lostKind: forcedEvents.length ? 'forced' : 'lost' });
let appWatch = null;

// ---------- 설정 / 상태 파일 ----------
function protect(text) {
  if (!text) return '';
  return safeStorage.isEncryptionAvailable() ? 'enc:' + safeStorage.encryptString(text).toString('base64') : text;
}
function unprotect(text) {
  if (!text?.startsWith('enc:')) return text || '';
  try { return safeStorage.decryptString(Buffer.from(text.slice(4), 'base64')); } catch { return ''; }
}
function loadConfig() {
  try {
    const c = JSON.parse(fs.readFileSync(CONFIG_FILE, 'utf8'));
    if (!c.supabaseUrl || !c.anonKey || !c.email) return null;
    return { ...c, password: unprotect(c.password), adminPin: unprotect(c.adminPin) };
  } catch { return null; }
}
function saveConfig(c) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
  fs.writeFileSync(CONFIG_FILE, JSON.stringify({ ...c, password: protect(c.password), adminPin: protect(c.adminPin) }, null, 2));
}
function loadState() {
  try { return { locked: true, mode: 'timed', remainingSec: 0, ...JSON.parse(fs.readFileSync(STATE_FILE, 'utf8')) }; } catch { return { locked: true, mode: 'timed', remainingSec: 0 }; }
}
function saveState() {
  try { fs.writeFileSync(STATE_FILE, JSON.stringify({ locked: st.locked, mode: st.mode, remainingSec: st.remainingSec, savedAt: Date.now() })); } catch {}
}
// PC를 끄면 남은 시간은 0으로 (다음에 켜면 잠긴 상태로 시작)
const OFF_GAP_MS = 3 * 60 * 1000; // 프로그램이 3분 넘게 꺼져 있었으면 PC가 꺼졌던 것으로 본다
function resetForPowerOff(kind = 'shutdown') {
  const logged = usage.powerOff(kind); // 사용 기록을 먼저 닫는다 (실제로 쓴 시간까지만)
  st.mode = 'timed'; st.remainingSec = 0; st.locked = true;
  saveState();
  // 관리자에게 '정상 종료'로 알린다 (비정상 종료 알림이 뜨지 않게)
  try {
    if (sb && st.connected && cfg) {
      return Promise.all([logged, sb.from('seats').update({ online: false, locked: true, mode: 'timed', remaining_sec: 0 }).eq('id', cfg.seatId).then(() => {}, () => {})]);
    }
  } catch {}
  return logged;
}

let cfg = null;
let sb = null;
let control = null;
let dbChannel = null;
let quitting = false;
const st = { ...loadState(), seatName: '', connected: false, menu: [], messages: [], orders: [], admins: 0 };
// 업데이트/자동 재시작처럼 잠깐 꺼졌다 켜진 경우만 시간을 이어 가고, 그 외(PC 켜기 등)는 0부터
if (!st.savedAt) { try { st.savedAt = fs.statSync(STATE_FILE).mtimeMs; } catch {} } // 예전 버전이 저장한 파일
if (!st.savedAt || Date.now() - st.savedAt > OFF_GAP_MS) { st.mode = 'timed'; st.remainingSec = 0; st.locked = true; }
delete st.savedAt;
if (forcedEvents.length) { st.mode = 'timed'; st.remainingSec = 0; st.locked = true; } // 강제 종료로 꺼졌으면 남은 시간도 없다
setInterval(saveState, 30_000);
const doneCommands = new Set();
// 업데이트 관문: 잠길 때마다(그리고 켜질 때) 업데이트를 먼저 확인한다. 끝날 때까지는 충전해도 잠금이 풀리지 않는다.
const gate = { busy: false, phase: 'idle', pct: 0, version: null };
const isLocked = () => st.locked || gate.busy;
let watchUntil = 0;

// ---------- 창 ----------
let lockWins = [];
let widgetWin = null;
let panelWin = null;
let adminWin = null;

const preload = path.join(__dirname, 'preload.js');
const page = (name) => path.join(__dirname, name);

function guardClose(win) {
  win.on('close', (e) => { if (!quitting) { e.preventDefault(); if (win === panelWin) win.hide(); } });
  // 종료 중(quitting)에 창이 실제로 닫히면 변수를 비운다. 닫힌 창을 다시 건드리면 'Object has been destroyed' 오류가 난다
  win.on('closed', () => {
    if (win === panelWin) panelWin = null;
    if (win === widgetWin) widgetWin = null;
    if (win === angelWin) angelWin = null;
    if (win === toastWin) toastWin = null;
  });
}
const alive = (w) => !!w && !w.isDestroyed();

function createLockWindows() {
  lockWins.forEach((w) => { if (!w.isDestroyed()) w.destroy(); });
  const primary = screen.getPrimaryDisplay();
  lockWins = screen.getAllDisplays().map((d) => {
    const w = new BrowserWindow({
      ...d.bounds, frame: false, show: false, skipTaskbar: true, resizable: false, movable: false,
      minimizable: false, maximizable: false, fullscreenable: true, backgroundColor: '#0b1020',
      webPreferences: { preload },
    });
    w.setAlwaysOnTop(true, 'screen-saver');
    w.on('session-end', () => { allowQuit('shutdown'); resetForPowerOff('shutdown'); }); // Windows 종료/재시작/로그오프
    w.setVisibleOnAllWorkspaces(true);
    w.loadFile(page('lock.html'), { query: { primary: d.id === primary.id ? '1' : '0' } });
    guardClose(w);
    return w;
  });
}

// 왼쪽 위 구석의 작은 반투명 알림. 포커스를 가져가지 않고(showInactive, focusable:false)
// 마우스도 통과시켜서 게임 조작/화면 전환에 영향을 주지 않는다. 5초 뒤 저절로 사라진다.
let toastWin = null;
let toastTimer = null;
const CORNER_TOAST = false; // 게임 보호: 전체 화면 게임 위에 창을 띄우지 않는다
function cornerToast(text) {
  if (!CORNER_TOAST || isLocked()) return;
  const wa = screen.getPrimaryDisplay().workArea;
  if (!toastWin || toastWin.isDestroyed()) {
    toastWin = new BrowserWindow({
      width: 260, height: 44, x: wa.x + 12, y: wa.y + 12,
      frame: false, transparent: true, resizable: false, show: false, skipTaskbar: true, hasShadow: false,
      focusable: false, minimizable: false, maximizable: false, webPreferences: { preload },
    });
    toastWin.setIgnoreMouseEvents(true);
    toastWin.setAlwaysOnTop(true, 'screen-saver', 1);
    toastWin.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true });
    toastWin.loadFile(page('toast.html'));
    guardClose(toastWin);
  }
  toastWin.setPosition(wa.x + 12, wa.y + 12);
  const show = () => { toastWin.webContents.send('toast', text); toastWin.showInactive(); };
  if (toastWin.webContents.isLoading()) toastWin.webContents.once('did-finish-load', show); else show();
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { if (toastWin && !toastWin.isDestroyed()) toastWin.hide(); }, 5600);
}

// 남은 시간 창: 어디를 잡아도 끌어서 옮길 수 있고, 화면 밖으로 나가지 않으며, 작게 접을 수 있다
const WIDGET_FILE = path.join(DATA_DIR, 'widget.json');
const WIDGET_SIZE = { full: { width: 330, height: 190 }, mini: { width: 190, height: 60 } };
// 수호천사 보호 중에는 작은 창 대신 큰 '수호천사 가족' 창을 따로 띄운다 (창 크기를 바꾸지 않고 처음부터 큰 창으로 만든다)
const ANGEL_SIZE = { width: 500, height: 470 };
const widgetMode = () => (widgetPref.mini ? 'mini' : 'full');
const prefSize = () => WIDGET_SIZE[widgetPref.mini ? 'mini' : 'full'];
let widgetPref = (() => { try { return JSON.parse(fs.readFileSync(WIDGET_FILE, 'utf8')); } catch { return {}; } })();
function saveWidgetPref() { try { fs.writeFileSync(WIDGET_FILE, JSON.stringify(widgetPref)); } catch {} }

function clampToScreen({ x, y, width, height }) {
  const wa = screen.getDisplayMatching({ x, y, width, height }).workArea;
  return {
    x: Math.round(Math.min(Math.max(x, wa.x), wa.x + wa.width - width)),
    y: Math.round(Math.min(Math.max(y, wa.y), wa.y + wa.height - height)),
    width, height,
  };
}
function defaultWidgetPos(size) {
  const wa = screen.getPrimaryDisplay().workArea;
  return { x: wa.x + wa.width - size.width - 16, y: wa.y + 16 };
}
function placeWidget() {
  if (!alive(widgetWin)) return;
  const mode = widgetMode(), size = WIDGET_SIZE[mode];
  // 저장된 위치는 보통 크기 기준. 크기가 달라도 오른쪽 위 모서리를 맞춘다
  const pos = Number.isFinite(widgetPref.x) ? { x: widgetPref.x + prefSize().width - size.width, y: widgetPref.y } : defaultWidgetPos(size);
  widgetWin.setBounds(clampToScreen({ ...pos, ...size }));
  widgetWin.webContents.send('widget:mini', mode === 'mini');
}

let angelWin = null;
function angelSize() {
  const wa = screen.getPrimaryDisplay().workArea;
  return { width: Math.min(ANGEL_SIZE.width, wa.width - 32), height: Math.min(ANGEL_SIZE.height, wa.height - 32) };
}
function angelPos(size) {
  if (Number.isFinite(widgetPref.ax)) return { x: widgetPref.ax, y: widgetPref.ay };
  // 처음에는 남은 시간 창이 있던 오른쪽 위에 맞춘다
  const wp = Number.isFinite(widgetPref.x) ? { x: widgetPref.x + prefSize().width - size.width, y: widgetPref.y } : defaultWidgetPos(size);
  return wp;
}
function placeAngel() {
  if (!angelWin || angelWin.isDestroyed()) return;
  const size = angelSize();
  angelWin.setBounds(clampToScreen({ ...angelPos(size), ...size }));
}
function createAngelWin() {
  const size = angelSize();
  angelWin = new BrowserWindow({
    ...size, ...clampToScreen({ ...angelPos(size), ...size }),
    frame: false, transparent: true, resizable: false, show: false, skipTaskbar: true, hasShadow: false,
    minimizable: false, maximizable: false, focusable: false, // 게임 창 포커스를 빼앗지 않는다
    webPreferences: { preload },
  });
  angelWin.setAlwaysOnTop(true, 'floating');
  angelWin.loadFile(page('angel.html'));
  angelWin.webContents.once('did-finish-load', () => { placeAngel(); render(); });
  guardClose(angelWin);
}

function createWidget() {
  const size = WIDGET_SIZE[widgetMode()];
  widgetWin = new BrowserWindow({
    ...size, ...defaultWidgetPos(size),
    frame: false, transparent: true, resizable: false, show: false, skipTaskbar: true, hasShadow: false,
    minimizable: false, maximizable: false, focusable: false, // 눌러도 게임 창에서 포커스를 빼앗지 않는다
    webPreferences: { preload },
  });
  widgetWin.setAlwaysOnTop(true, 'floating');
  widgetWin.loadFile(page('widget.html'));
  widgetWin.webContents.on('did-finish-load', placeWidget);
  guardClose(widgetWin);
  placeWidget();
}

let dragTimer = null, dragWin = null;
function stopDrag() {
  if (!dragTimer) return;
  clearInterval(dragTimer); dragTimer = null;
  const win = dragWin; dragWin = null;
  if (!win || win.isDestroyed()) return;
  const b = clampToScreen(win.getBounds());
  win.setBounds(b);
  if (win === angelWin) { widgetPref.ax = b.x; widgetPref.ay = b.y; }
  else { widgetPref.x = b.x + b.width - prefSize().width; widgetPref.y = b.y; }
  saveWidgetPref();
}
ipcMain.on('widget:dragStart', (e) => {
  const win = BrowserWindow.fromWebContents(e.sender);
  if (!win || (win !== widgetWin && win !== angelWin)) return;
  stopDrag();
  dragWin = win;
  const start = screen.getCursorScreenPoint();
  const [wx, wy] = win.getPosition();
  const off = { x: start.x - wx, y: start.y - wy };
  const startedAt = Date.now();
  dragTimer = setInterval(() => {
    const p = screen.getCursorScreenPoint();
    if (win.isDestroyed()) return stopDrag();
    win.setPosition(p.x - off.x, p.y - off.y);
    if (Date.now() - startedAt > 30_000) stopDrag(); // 마우스를 놓친 경우 대비
  }, 15);
});
ipcMain.on('widget:dragEnd', stopDrag);

// (게임 보호) 예전에는 2초마다 남은 시간 창을 맨 위로 다시 올렸는데,
// 전체 화면 게임(발로란트 등)이 그때마다 화면을 빼앗겨 튕기는 원인이 되어 없앴다.
// 남은 시간 창은 '항상 위'로만 두고, 게임 전체 화면 위에는 억지로 올리지 않는다.
ipcMain.on('widget:mini', (_e, mini) => {
  if (!alive(widgetWin)) return;
  // 접을 때/펼 때 오른쪽 위 모서리를 기준으로 유지
  const b = widgetWin.getBounds();
  const size = WIDGET_SIZE[mini ? 'mini' : 'full'];
  widgetPref.mini = !!mini;
  widgetPref.x = b.x + b.width - size.width; widgetPref.y = b.y;
  saveWidgetPref(); placeWidget();
});
ipcMain.on('widget:reset', (e) => {
  if (BrowserWindow.fromWebContents(e.sender) === angelWin) { delete widgetPref.ax; delete widgetPref.ay; saveWidgetPref(); placeAngel(); return; }
  delete widgetPref.x; delete widgetPref.y; saveWidgetPref(); placeWidget();
});

function openPanel(tab = 'menu') {
  if (!alive(panelWin)) {
    panelWin = new BrowserWindow({
      width: 560, height: 720, show: false, resizable: true, minimizable: false, autoHideMenuBar: true,
      title: '주문 · 채팅 · 이용권 · 수호천사 · 사용 기록', backgroundColor: '#ffffff', webPreferences: { preload },
    });
    panelWin.loadFile(page('panel.html'));
    guardClose(panelWin);
    panelWin.webContents.once('did-finish-load', () => { sendAll('state', uiState()); panelWin.webContents.send('tab', tab); });
  } else {
    panelWin.webContents.send('tab', tab);
  }
  // 잠금 화면보다 위에 보이게
  panelWin.setAlwaysOnTop(true, 'screen-saver', 2);
  panelWin.center();
  panelWin.show();
  panelWin.focus();
}

function openAdmin(mode) {
  if (adminWin) { adminWin.focus(); return; }
  adminWin = new BrowserWindow({
    width: 520, height: mode === 'setup' ? 780 : 360, resizable: false, autoHideMenuBar: true,
    title: mode === 'setup' ? 'PC방 손님 프로그램 설정' : '관리자 메뉴', webPreferences: { preload },
  });
  adminWin.setAlwaysOnTop(true, 'screen-saver', 3);
  adminWin.loadFile(page('setup.html'), { query: { mode, needPin: cfg?.adminPin ? '1' : '0' } });
  adminWin.on('closed', () => { adminWin = null; if (!cfg && !quitting) { allowQuit('setup'); app.quit(); } });
}

function sendAll(ch, payload) {
  for (const w of [...lockWins, widgetWin, angelWin, panelWin]) if (w && !w.isDestroyed()) w.webContents.send(ch, payload);
}
function uiState() {
  return {
    version: CODE_VERSION, updated: CODE_DATE, gate: { ...gate }, gateHold: gate.busy && !st.locked, seatName: st.seatName || cfg?.seatName || '', locked: isLocked(), mode: st.mode, remainingSec: st.remainingSec,
    connected: st.connected, menu: st.menu, messages: st.messages, orders: st.orders, passes: activePasses(),
    angels: activeAngels(), angel: angelInfo(), angelUsedToday: angelUsedToday(),
    usage: usage.live(),
  };
}
let prevLocked = null;
function render() {
  const locked = isLocked();
  sendAll('state', uiState());
  for (const w of lockWins) {
    if (w.isDestroyed()) continue;
    if (locked && !w.isVisible()) { w.show(); w.focus(); }
    if (!locked && w.isVisible()) w.hide();
  }
  // 수호천사 보호 중이면 큰 가족 창, 아니면 평소의 남은 시간 창
  const showAngel = !locked && angelOn() && !!cfg;
  if (showAngel && (!angelWin || angelWin.isDestroyed())) createAngelWin();
  if (angelWin && !angelWin.isDestroyed()) {
    if (showAngel && !angelWin.isVisible() && !angelWin.webContents.isLoading()) angelWin.showInactive();
    if (!showAngel && angelWin.isVisible()) angelWin.hide();
  }
  if (alive(widgetWin)) {
    const showWidget = !locked && !showAngel;
    if (showWidget && !widgetWin.isVisible()) widgetWin.showInactive();
    if (!showWidget && widgetWin.isVisible()) widgetWin.hide();
  }
  // 잠기는 순간 업데이트 확인
  if (st.locked && prevLocked === false) runGate();
  prevLocked = st.locked;
}

// 잠금 상태에서 다른 창이 앞으로 나오지 않게 주기적으로 다시 올린다
setInterval(() => {
  if (!isLocked()) return;
  if ((alive(panelWin) && panelWin.isVisible()) || adminWin) return;
  for (const w of lockWins) if (!w.isDestroyed()) { w.setAlwaysOnTop(true, 'screen-saver'); w.moveTop(); }
  if (alive(lockWins[0])) lockWins[0].focus();
}, 1500);

// ---------- 시간 계산 ----------
setInterval(() => {
  if (!cfg) return;
  // 사용 기록: 잠금이 풀려 있는 1초마다 '실제 사용' 1초, 맨 앞 프로그램에도 1초
  usage.tick({ using: !isLocked(), mode: st.mode, remainingSec: st.remainingSec, app: appWatch?.current() });
  if (!isLocked() && st.mode === 'timed') {
    st.remainingSec = Math.max(0, st.remainingSec - 1);
    if (st.remainingSec === 300) {
      const canAngel = activeAngels().length && !angelOn() && !angelUsedToday();
      notice('남은 시간이 5분입니다.' + (canAngel ? ' 👼 지금부터 수호천사를 부를 수 있어요.' : ''));
      cornerToast('⏱ 남은 시간 5분' + (canAngel ? ' · 👼 수호천사 가능' : ''));
    }
    if (st.remainingSec === 60) { notice('남은 시간이 1분입니다. 작업을 저장하세요.'); cornerToast('⏱ 남은 시간 1분 · 저장하세요'); }
    if (st.remainingSec > 0 && st.remainingSec % 1800 === 0) {
      const m = st.remainingSec / 60;
      cornerToast(`⏱ 남은 시간 ${[m >= 60 ? Math.floor(m / 60) + '시간' : '', m % 60 ? (m % 60) + '분' : ''].filter(Boolean).join(' ')}`);
    }
    if (st.remainingSec === 0) {
      st.locked = true;
      usage.hint('time_up');
      notice('사용 시간이 끝났습니다.');
      saveState(); pushSeat(); render();
      return;
    }
  }
  if (st.angel && !angelOn()) angelEnded('time');
  sendAll('tick', { angelLeft: angelOn() ? Math.max(0, Math.round((st.angel.until - Date.now()) / 1000)) : null, remainingSec: st.remainingSec, locked: isLocked(), mode: st.mode, usedSec: usage.live().current?.usedSec ?? null });
  if (st.remainingSec % 10 === 0) saveState();
}, 1000);

function notice(text) {
  sendAll('notice', text);
}

// ---------- 관리자 명령 ----------
// 수호천사 보호 중에는 끊는 명령을 따르지 않는다 (서버에서도 막지만, 그 전에 들어온 명령 대비)
const ANGEL_BLOCK = (c) => ['lock', 'endSession', 'shutdown', 'restart'].includes(c.cmd)
  || (c.cmd === 'addTime' && Number(c.arg) < 0)
  || (c.cmd === 'setTime' && Number(c.arg) * 60 < st.remainingSec - 60);
function applyCommand(c) {
  if (doneCommands.has(c.id)) return;
  if (angelOn() && ANGEL_BLOCK(c)) {
    doneCommands.add(c.id);
    // 방금 비밀번호로 해제됐을 수 있으니 서버에서 다시 확인한다
    loadAngels().then(() => {
      if (angelOn()) { markDone(c.id); notice('👼 수호천사가 지켜 주고 있어서 관리자 명령을 막았어요.'); render(); }
      else { doneCommands.delete(c.id); applyCommand(c); }
    });
    return;
  }
  doneCommands.add(c.id);
  const before = { sec: st.remainingSec, mode: st.mode, using: usage.active() };
  switch (c.cmd) {
    case 'addTime': {
      const min = Math.max(-600, Math.min(1440, Number(c.arg) || 0));
      if (st.mode !== 'timed') { st.mode = 'timed'; st.remainingSec = 0; }
      st.remainingSec = Math.max(0, st.remainingSec + min * 60);
      st.locked = st.remainingSec <= 0;
      if (min > 0) notice(`${min >= 60 ? Math.floor(min / 60) + '시간 ' : ''}${min % 60 ? (min % 60) + '분 ' : ''}충전되었습니다.`);
      break;
    }
    case 'setTime': { // 남은 시간을 정확히 이 값(분)으로 맞춘다
      const min = Math.max(0, Math.min(1440, Number(c.arg) || 0));
      st.mode = 'timed';
      st.remainingSec = min * 60;
      st.locked = st.remainingSec <= 0;
      if (min > 0) notice(`남은 시간이 ${min >= 60 ? Math.floor(min / 60) + '시간 ' : ''}${min % 60 ? (min % 60) + '분' : ''}으로 설정되었습니다.`.replace(' 으로', '으로'));
      break;
    }
    case 'setFree': st.mode = 'free'; st.locked = false; notice('시간 제한 없이 사용할 수 있습니다.'); break;
    case 'lock': st.locked = true; usage.hint('admin_lock'); break;
    case 'unlock':
      if (st.mode === 'timed' && st.remainingSec <= 0) st.mode = 'free';
      st.locked = false; break;
    case 'endSession': usage.hint('admin_end'); st.mode = 'timed'; st.remainingSec = 0; st.locked = true; notice('사용이 종료되었습니다.'); break;
    case 'notice': notice(String(c.arg || '').slice(0, 300)); break;
    case 'shutdown':
    case 'restart':
      notice(c.cmd === 'shutdown' ? '관리자가 PC를 종료합니다.' : '관리자가 PC를 다시 시작합니다.');
      markDone(c.id).finally(async () => {
        await Promise.race([resetForPowerOff(c.cmd), new Promise((r) => setTimeout(r, 3500))]);
        allowQuit('shutdown');
        if (process.platform === 'win32') exec(`shutdown ${c.cmd === 'shutdown' ? '/s' : '/r'} /t 5`);
      });
      return;
  }
  // 사용 중에 시간을 충전/조정하면 '받은 시간'에 반영
  if (before.using && before.mode === 'timed' && st.mode === 'timed' && (c.cmd === 'addTime' || c.cmd === 'setTime')) usage.granted(st.remainingSec - before.sec);
  saveState(); pushSeat(); render();
  markDone(c.id);
}
async function markDone(id) {
  try { await sb.from('commands').update({ done: true }).eq('id', id); } catch {}
}

// ---------- Supabase ----------
async function pushSeat(extra = {}) {
  if (!sb || !st.connected) return;
  const { error } = await sb.from('seats').update({
    locked: isLocked(), mode: st.mode, remaining_sec: st.remainingSec, online: true, last_seen: new Date().toISOString(), ...extra,
  }).eq('id', cfg.seatId);
  if (error) console.error('seat update', error.message);
}

async function connect() {
  st.connected = false; render();
  try {
    if (!sb) sb = createClient(cfg.supabaseUrl, cfg.anonKey, { auth: { persistSession: false, autoRefreshToken: true } });
    const { error: authErr } = await sb.auth.signInWithPassword({ email: cfg.email, password: cfg.password });
    if (authErr) throw new Error('로그인 실패: ' + authErr.message);

    // 좌석 등록 (없으면 만들고, 이름은 관리자가 바꾼 값을 따른다)
    const { data: seat, error: seatErr } = await sb.from('seats').select('*').eq('id', cfg.seatId).maybeSingle();
    if (seatErr) throw new Error(seatErr.message);
    if (!seat) {
      const { error } = await sb.from('seats').insert({
        id: cfg.seatId, name: cfg.seatName, locked: st.locked, mode: st.mode, remaining_sec: st.remainingSec, online: true,
      });
      if (error) throw new Error(error.message);
      st.seatName = cfg.seatName;
    } else {
      st.seatName = seat.name;
      // 관리자 화면이 기억하는 시간이 더 적으면 그쪽을 따른다 (꺼진 사이 조작 방지)
      if (seat.mode === 'timed' && st.mode === 'timed' && seat.remaining_sec < st.remainingSec) st.remainingSec = seat.remaining_sec;
    }
    st.connected = true;
    await pushSeat();
    usage.setSeat(cfg.seatId, st.seatName);
    usage.setClient(sb);
    flushAdminNotes();

    await loadData();
    subscribe();

    const { data: pending } = await sb.from('commands').select('*').eq('seat_id', cfg.seatId).eq('done', false).order('id');
    (pending || []).forEach(applyCommand);
    render();
  } catch (e) {
    console.error(e.message);
    st.connected = false;
    sendAll('status', String(e.message || e));
    render();
    setTimeout(connect, 15000);
  }
}

async function loadData() {
  const [menu, msgs, orders] = await Promise.all([
    sb.from('menu').select('*').order('sort').order('id'),
    sb.from('messages').select('*').eq('seat_id', cfg.seatId).order('created_at', { ascending: false }).limit(50),
    sb.from('orders').select('*').eq('seat_id', cfg.seatId).order('created_at', { ascending: false }).limit(10),
  ]);
  st.menu = menu.data || [];
  st.messages = (msgs.data || []).reverse();
  st.orders = orders.data || [];
  await loadPasses();
  await loadAngels();
}
// 수호천사 발동권: 이 PC가 가진 안 쓴 권 + 지금 보호 중인 권 (SQL 설정 전이면 빈 목록)
async function loadAngels() {
  if (!sb || !cfg) return;
  const { data, error } = await sb.from('angel_passes').select('*').eq('seat_id', cfg.seatId)
    .or(`status.eq.active,and(status.eq.used,used_at.gte.${new Date(Date.now() - 36 * 3600_000).toISOString()})`).order('created_at');
  if (error) { st.angels = []; return; }
  st.angels = data || [];
  syncAngel();
}
function activeAngels() {
  const now = Date.now();
  return (st.angels || []).filter((p) => p.status === 'active' && (!p.expires_at || new Date(p.expires_at).getTime() > now))
    .map(({ id, minutes, holder, note, expires_at }) => ({ id, minutes, holder, note, expires_at }));
}
const kstDay = (t) => new Date(new Date(t).getTime() + 9 * 3600_000).toISOString().slice(0, 10);
function angelUsedToday() {
  const today = kstDay(Date.now());
  return (st.angels || []).some((p) => p.status === 'used' && p.used_at && kstDay(p.used_at) === today);
}
// 서버 기록으로 보호 상태를 맞춘다
function syncAngel() {
  const on = (st.angels || []).find((p) => p.status === 'used' && !p.ended_at && new Date(p.protect_until).getTime() > Date.now());
  const was = st.angel;
  if (on) {
    st.angel = { id: on.id, minutes: on.minutes, until: new Date(on.protect_until).getTime() };
    if (!was) { placeWidget(); render(); }
  } else if (was) {
    const row = (st.angels || []).find((p) => p.id === was.id);
    angelEnded(row?.ended_at ? 'released' : 'time');
  }
}
function angelOn() { return !!st.angel && st.angel.until > Date.now(); }
function angelInfo() { return angelOn() ? { ...st.angel } : null; }
function angelEnded(why) {
  if (!st.angel) return;
  st.angel = null;
  notice(why === 'released' ? '👼 관리자가 비밀번호로 수호천사 보호를 풀었어요.' : '👼 수호천사 보호 시간이 끝났어요. 이제 마무리해요!');
  cornerToast(why === 'released' ? '👼 수호천사 보호 해제됨' : '👼 수호천사 보호 끝');
  placeWidget(); render();
}
// 추가 이용권: 관리자가 이 PC에 넣어 준 이용권 (SQL 설정 전이면 빈 목록)
async function loadPasses() {
  const { data, error } = await sb.from('passes').select('*').eq('seat_id', cfg.seatId).eq('status', 'active').order('created_at');
  st.passes = error ? [] : data || [];
}
function activePasses() {
  const now = Date.now();
  return (st.passes || []).filter((p) => p.status === 'active' && (!p.expires_at || new Date(p.expires_at).getTime() > now));
}
const fmtMinKo = (m) => [m >= 60 ? Math.floor(m / 60) + '시간' : '', m % 60 ? (m % 60) + '분' : ''].filter(Boolean).join(' ');

function subscribe() {
  if (dbChannel) sb.removeChannel(dbChannel);
  if (control) sb.removeChannel(control);
  const seatFilter = `seat_id=eq.${cfg.seatId}`;
  dbChannel = sb.channel('agent-db-' + cfg.seatId)
    .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'commands', filter: seatFilter }, (p) => applyCommand(p.new))
    .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages', filter: seatFilter }, (p) => {
      if (st.messages.some((m) => m.id === p.new.id)) return;
      st.messages.push(p.new); st.messages = st.messages.slice(-100);
      sendAll('state', uiState());
      if (p.new.sender === 'admin') notice('관리자: ' + p.new.text); // 게임 중 포커스를 뺏지 않도록 창을 자동으로 열지 않는다
    })
    .on('postgres_changes', { event: '*', schema: 'public', table: 'orders', filter: seatFilter }, (p) => {
      if (!p.new?.id) return;
      const i = st.orders.findIndex((o) => o.id === p.new.id);
      const before = i >= 0 ? st.orders[i].status : null;
      if (i >= 0) st.orders[i] = p.new; else st.orders.unshift(p.new);
      const label = { making: '준비 중입니다', done: '완료되었습니다. 곧 가져다 드릴게요', canceled: '취소되었습니다' }[p.new.status];
      if (before && before !== p.new.status && label) notice(`주문하신 ${p.new.items.map((x) => x.name).join(', ')}: ${label}.`);
      sendAll('state', uiState());
    })
    .on('postgres_changes', { event: '*', schema: 'public', table: 'passes', filter: seatFilter }, (p) => {
      const had = (st.passes || []).some((x) => x.id === p.new?.id);
      if (p.eventType === 'DELETE') st.passes = (st.passes || []).filter((x) => x.id !== p.old.id);
      else {
        st.passes = (st.passes || []).filter((x) => x.id !== p.new.id);
        if (p.new.status === 'active') st.passes.push(p.new);
        if (!had && p.new.status === 'active') notice(`🎟 이용권이 도착했어요 (${fmtMinKo(p.new.minutes)}). 원할 때 [🎟 이용권]을 눌러 사용하세요.`);
      }
      sendAll('state', uiState());
    })
    .on('postgres_changes', { event: '*', schema: 'public', table: 'angel_passes', filter: seatFilter }, (p) => {
      const had = (st.angels || []).some((x) => x.id === p.new?.id);
      if (p.eventType === 'DELETE') st.angels = (st.angels || []).filter((x) => x.id !== p.old.id);
      else {
        st.angels = (st.angels || []).filter((x) => x.id !== p.new.id).concat(p.new);
        if (!had && p.new.status === 'active') notice(`👼 수호천사 발동권이 도착했어요! 남은 시간이 5분 미만일 때 [👼 수호천사]를 눌러 부를 수 있어요.`);
      }
      syncAngel();
      sendAll('state', uiState());
    })
    .on('postgres_changes', { event: '*', schema: 'public', table: 'menu' }, async () => {
      const { data } = await sb.from('menu').select('*').order('sort').order('id');
      st.menu = data || []; sendAll('state', uiState());
    })
    .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'seats', filter: `id=eq.${cfg.seatId}` }, (p) => {
      if (p.new.name && p.new.name !== st.seatName) { st.seatName = p.new.name; usage.setSeat(cfg.seatId, st.seatName); sendAll('state', uiState()); }
    })
    .subscribe((status) => {
      if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT') sendAll('status', '실시간 연결 재시도 중…');
    });

  // 화면 전송 채널: 관리자가 접속해 있을 때만 화면을 보낸다
  control = sb.channel(CONTROL_CHANNEL, { config: { private: true, broadcast: { self: false }, presence: { key: 'agent:' + cfg.seatId } } })
    .on('presence', { event: 'sync' }, () => {
      st.admins = Object.keys(control.presenceState()).filter((k) => k.startsWith('admin:')).length;
    })
    .on('broadcast', { event: 'watch' }, ({ payload }) => {
      if (payload?.seatId === cfg.seatId) watchUntil = Date.now() + 10_000;
    })
    .subscribe(async (status) => {
      if (status === 'SUBSCRIBED') await control.track({ role: 'agent', seatId: cfg.seatId, version: CODE_VERSION, updated: CODE_DATE });
    });
}

// 15초마다 접속 상태와 남은 시간 기록, 끊겼으면 다시 연결
setInterval(async () => {
  if (!cfg || !sb) return;
  if (st.connected) await pushSeat();
  // 다른 PC로 옮겨진 이용권 등은 실시간 알림이 안 올 수 있어 1분마다 다시 읽는다
  if (st.connected && ++passTick % 4 === 0) {
    const before = JSON.stringify(activePasses());
    await loadPasses();
    if (JSON.stringify(activePasses()) !== before) sendAll('state', uiState());
  }
  // 수호천사: 비밀번호 해제를 놓치지 않게 15초마다 확인
  if (st.connected) {
    const before = JSON.stringify([activeAngels(), angelInfo()?.id]);
    await loadAngels();
    if (JSON.stringify([activeAngels(), angelInfo()?.id]) !== before) sendAll('state', uiState());
  }
}, 15000);
let passTick = 0;

// ---------- 화면 캡처 ----------
async function capture(width, quality, maxBytes) {
  const d = screen.getPrimaryDisplay();
  const height = Math.round(width * d.size.height / d.size.width);
  const sources = await desktopCapturer.getSources({ types: ['screen'], thumbnailSize: { width, height } });
  const src = sources.find((s) => s.display_id === String(d.id)) || sources[0];
  if (!src) return null;
  let q = quality, buf = src.thumbnail.toJPEG(q);
  while (buf.length * 1.37 > maxBytes && q > 20) { q -= 10; buf = src.thumbnail.toJPEG(q); }
  return 'data:image/jpeg;base64,' + buf.toString('base64');
}
let lastThumb = 0;
let capturing = false;
setInterval(async () => {
  if (!control || !st.connected || capturing) return;
  const watching = watchUntil > Date.now();
  const now = Date.now();
  if (!watching && (st.admins === 0 || now - lastThumb < 5000)) return;
  capturing = true;
  try {
    if (watching) {
      const img = await capture(1280, 60, 200_000);
      if (img) control.send({ type: 'broadcast', event: 'frame', payload: { seatId: cfg.seatId, img } });
    }
    if (now - lastThumb >= 5000 && st.admins > 0) {
      lastThumb = now;
      const img = await capture(360, 55, 40_000);
      if (img) control.send({ type: 'broadcast', event: 'thumb', payload: { seatId: cfg.seatId, img } });
    }
  } catch (e) { console.error('capture', e.message); }
  capturing = false;
}, 1000);

// ---------- 화면(렌더러)에서 오는 요청 ----------
ipcMain.handle('getState', () => uiState());
ipcMain.handle('usage:history', async () => {
