});
ipcMain.on('openPanel', (_e, tab) => openPanel(tab));
ipcMain.on('hidePanel', () => { if (alive(panelWin)) panelWin.hide(); });
ipcMain.handle('chat', async (_e, text) => {
  text = String(text || '').trim().slice(0, 500);
  if (!text || !st.connected) return { error: '연결되지 않았습니다.' };
  const { data, error } = await sb.from('messages').insert({ seat_id: cfg.seatId, sender: 'guest', text }).select().single();
  if (error) return { error: error.message };
  if (!st.messages.some((m) => m.id === data.id)) st.messages.push(data);
