});
ipcMain.handle('call', async () => {
  if (!st.connected) return { error: '연결되지 않았습니다.' };
  const { error } = await sb.from('messages').insert({ seat_id: cfg.seatId, sender: 'guest', kind: 'call', text: '카운터 호출' });
  return error ? { error: error.message } : { ok: true };
});
ipcMain.handle('order', async (_e, { items, note } = {}) => {
  if (!st.connected) return { error: '연결되지 않았습니다.' };
  const list = (items || []).map((it) => {
    const m = st.menu.find((x) => x.id === it.id && !x.sold_out);
    return m ? { id: m.id, name: m.name, price: m.price, qty: Math.max(1, Math.min(20, Number(it.qty) || 1)) } : null;
  }).filter(Boolean);
  if (!list.length) return { error: '주문할 메뉴를 골라 주세요.' };
  const { data, error } = await sb.from('orders').insert({
    seat_id: cfg.seatId, seat_name: st.seatName, items: list, note: String(note || '').slice(0, 200),
    total: list.reduce((a, b) => a + b.price * b.qty, 0),
  }).select().single();
  if (error) return { error: error.message };
  if (!st.orders.some((o) => o.id === data.id)) st.orders.unshift(data);
  sendAll('state', uiState());
  return { ok: true };
});

// 이용권 사용: 서버에서 한 번만 쓰이게 처리하고, 시간 추가 명령을 받아 바로 적용한다
ipcMain.handle('usePass', async (_e, id) => {
  if (!st.connected) return { error: '관리 서버에 연결되지 않았습니다. 잠시 후 다시 시도해 주세요.' };
  if (st.mode === 'free' && !isLocked()) return { error: '지금은 시간 제한 없이 이용 중이라 이용권이 필요 없어요. 나중에 사용하세요.' };
  const { data, error } = await sb.rpc('use_pass', { p_id: Number(id), p_seat: cfg.seatId });
  if (error) return { error: error.message };
  st.passes = (st.passes || []).filter((x) => x.id !== Number(id));
  if (!data?.ok) { sendAll('state', uiState()); return { error: data?.error || '이용권을 사용할 수 없습니다.' }; }
  try {
    const { data: c } = await sb.from('commands').select('*').eq('id', data.command_id).maybeSingle();
    if (c) applyCommand(c); // 같은 명령이 두 번 적용되지는 않는다
  } catch {}
  sendAll('state', uiState());
  return { ok: true, label: fmtMinKo(data.minutes) };
});

// 수호천사 발동: 남은 시간 5분 미만일 때만. 서버가 한 번만 쓰이게 처리하고 보호 시간만큼 시간을 더해 준다
ipcMain.handle('useAngel', async (_e, id) => {
  if (!st.connected) return { error: '관리 서버에 연결되지 않았습니다. 잠시 후 다시 시도해 주세요.' };
  if (angelOn()) return { error: '이미 수호천사가 지켜 주고 있어요.' };
  if (isLocked() || st.mode !== 'timed') return { error: '시간제로 이용 중일 때만 부를 수 있어요.' };
  if (st.remainingSec >= 300) return { error: `남은 시간이 5분 미만일 때만 부를 수 있어요. (지금 ${Math.ceil(st.remainingSec / 60)}분 남음)` };
  if (angelUsedToday()) return { error: '수호천사는 하루에 한 번만 부를 수 있어요. 내일 다시 쓸 수 있어요.' };
  await pushSeat(); // 서버가 남은 시간을 정확히 알도록 먼저 기록
  const { data, error } = await sb.rpc('use_angel', { p_id: Number(id), p_seat: cfg.seatId });
  if (error) return { error: error.message };
  if (!data?.ok) { await loadAngels(); sendAll('state', uiState()); return { error: data?.error || '수호천사를 부를 수 없습니다.' }; }
  try {
    const { data: c } = await sb.from('commands').select('*').eq('id', data.command_id).maybeSingle();
    if (c) applyCommand(c);
  } catch {}
  await loadAngels();
  if (!st.angel) { st.angel = { id: Number(id), minutes: data.minutes, until: Date.now() + data.minutes * 60_000 }; placeWidget(); }
  cornerToast(`👼 수호천사 발동! ${data.minutes}분 동안 지켜 줄게요`);
  sendAll('state', uiState()); render();
  return { ok: true, minutes: data.minutes };
});

// 관리자 메뉴 (Ctrl+Alt+Shift+F12): 설정 변경 / 프로그램 종료
ipcMain.handle('admin:check', (_e, pin) => !cfg?.adminPin || String(pin) === cfg.adminPin);
ipcMain.handle('admin:getConfig', (_e, pin) => {
  if (cfg?.adminPin && String(pin) !== cfg.adminPin) return null;
  return cfg ? { ...cfg, password: '', adminPin: '', blockTaskMgr: cfg.blockTaskMgr !== false } : { seatName: '', supabaseUrl: '', anonKey: '', email: '', blockTaskMgr: true };
});
ipcMain.handle('admin:save', async (_e, { pin, config }) => {
  if (cfg?.adminPin && String(pin) !== cfg.adminPin) return { error: '관리자 PIN이 틀렸습니다.' };
  const next = {
    supabaseUrl: String(config.supabaseUrl || '').trim().replace(/\/(rest|auth|realtime)\/v1.*$/, '').replace(/\/+$/, ''),
    anonKey: String(config.anonKey || '').trim(),
    email: String(config.email || '').trim(),
    password: config.password ? String(config.password) : (cfg?.password || ''),
    seatName: String(config.seatName || '').trim().slice(0, 30) || 'PC',
    adminPin: config.adminPin ? String(config.adminPin) : (cfg?.adminPin || ''),
    seatId: cfg?.seatId || crypto.randomUUID(),
    blockTaskMgr: config.blockTaskMgr !== false,
  };
  if (!/^https?:\/\/.+/.test(next.supabaseUrl) || !next.anonKey || !next.email || !next.password) return { error: '모든 항목을 입력해 주세요.' };
  // 저장 전에 접속 확인
  const test = createClient(next.supabaseUrl, next.anonKey, { auth: { persistSession: false } });
  const { error } = await test.auth.signInWithPassword({ email: next.email, password: next.password });
  if (error) return { error: '로그인 확인 실패: ' + error.message };
  const { data: role } = await test.rpc('my_role');
  if (role !== 'agent') return { error: '이 계정은 손님 PC용(agent) 역할이 아닙니다. 설치 안내의 SQL을 확인하세요.' };
  const first = !cfg;
  const nameChanged = cfg && cfg.seatName !== next.seatName;
  saveConfig(next);
  cfg = next;
  if (first) { startMain(); startWatchdog(); startGuard(); }
  else {
    applyTaskMgrBlock();
    if (sb) { await sb.removeAllChannels(); sb = null; }
    await connect();
    if (nameChanged && st.connected) { await sb.from('seats').update({ name: next.seatName }).eq('id', cfg.seatId); st.seatName = next.seatName; }
  }
  adminWin?.close();
  return { ok: true };
});
ipcMain.handle('admin:quit', async (_e, pin) => {
  if (cfg?.adminPin && String(pin) !== cfg.adminPin) return { error: '관리자 PIN이 틀렸습니다.' };
  await shutdownApp();
  return { ok: true };
});

// ---------- 강제 종료 방지 ----------
// 감시 프로세스와 서로를 지켜본다. 한쪽이 강제로 꺼지면 다른 쪽이 다시 살린다.
let watchdog = null;
function startWatchdog() {
  if (quitting || process.env.PCBANG_NO_WATCHDOG) return;
  const relaunchArgs = app.isPackaged ? process.argv.slice(1) : [app.getAppPath(), ...process.argv.slice(2)];
  const script = path.join(__dirname, 'watchdog.js').replace('app.asar' + path.sep, 'app.asar.unpacked' + path.sep);
  watchdog = spawn(process.execPath, [script, String(process.pid), QUIT_FLAG, process.execPath, ...relaunchArgs], {
    env: { ...process.env, ELECTRON_RUN_AS_NODE: '1' }, detached: true, stdio: 'ignore', windowsHide: true,
  });
  watchdog.on('exit', () => { watchdog = null; if (!quitting) setTimeout(startWatchdog, 1000); });
  watchdog.unref();
}
let guard = null;
// 정상 종료 표시. kind: pin(관리자 PIN) / update / shutdown / setup
// 감시 스크립트가 보기 전에 quit-ok를 먼저 쓰고 나서 감시 대상에서 빠진다 (순서 중요)
function allowQuit(kind = 'other') {
  quitting = true;
  try { fs.writeFileSync(QUIT_FLAG, `${process.pid} ${kind}`); } catch {}
  appWatch?.stop();
  guard?.stop();
  // Windows 종료/로그오프가 취소되는 등 실제로 꺼지지 않았으면 90초 뒤 감시를 다시 켠다 (감시가 꺼진 채 남지 않게)
  clearTimeout(quitRecoverTimer);
  quitRecoverTimer = setTimeout(recoverFromQuit, 90_000);
}
let quitRecoverTimer = null;
function recoverFromQuit() {
  if (!quitting) return;
  console.log('종료가 진행되지 않아 감시를 다시 켭니다');
  quitting = false;
  try { fs.unlinkSync(QUIT_FLAG); } catch {}
  appWatch = createAppWatcher(console.log);
  guard = null; startGuard();
  if (!watchdog) startWatchdog();
  if (lockWins.some((w) => w.isDestroyed())) createLockWindows();
  if (!alive(widgetWin)) createWidget();
  render();
}

// 강제 종료 감시 (Windows 작업 스케줄러) + 작업 관리자 막기
function startGuard() {
  applyTaskMgrBlock();
  if (!app.isPackaged || process.env.PCBANG_NO_WATCHDOG || guard) return;
  guard = setupGuard(DATA_DIR, {
    log: console.log,
    onTamper: (why) => notifyAdmin(`⚠️ [자동 알림] ${why}. 누군가 강제 종료 감시를 끄려고 한 것 같아요. 다시 켜 두었어요.`),
  });
}
function applyTaskMgrBlock() {
  if (app.isPackaged && process.platform === 'win32' && cfg) setTaskMgrBlock(cfg.blockTaskMgr !== false, console.log);
}

// 관리자에게 알림 (채팅으로 보낸다. 연결이 안 돼 있으면 연결된 뒤에 보낸다)
const adminNotes = [];
function notifyAdmin(text) { adminNotes.push(text); flushAdminNotes(); }
async function flushAdminNotes() {
  if (!sb || !st.connected || !cfg) return;
  while (adminNotes.length) {
    const { error } = await sb.from('messages').insert({ seat_id: cfg.seatId, sender: 'guest', text: adminNotes[0] });
    if (error) return;
    adminNotes.shift();
  }
}
setInterval(flushAdminNotes, 15000);
{
  const p2 = (n) => String(n).padStart(2, '0');
  const at = (d) => `${d.getMonth() + 1}/${d.getDate()} ${p2(d.getHours())}:${p2(d.getMinutes())}`;
  const WHY = { killed: '프로그램이 강제로 종료돼서', frozen: '프로그램을 일시 중지(멈춤)시켜서', 'tripped-again': '강제 종료 뒤 끄기를 막으려 해서' };
  for (const e of forcedEvents) notifyAdmin(`⚠️ [자동 알림] ${at(e.at)} ${WHY[e.reason] || '강제 종료가 감지돼서'} 약속대로 PC를 껐어요.`);
}

async function shutdownApp() {
  await usage.powerOff('quit');
  if (app.isPackaged && process.platform === 'win32') await setTaskMgrBlock(false); // 관리자가 쓸 수 있게 작업 관리자를 다시 풀어 준다
  allowQuit('pin');
  saveState();
  try { if (st.connected) await sb.from('seats').update({ online: false, remaining_sec: st.remainingSec }).eq('id', cfg.seatId); } catch {}
  app.quit();
}

// ---------- 자동 업데이트 ----------
// 새 버전을 받아 두었다가, 손님이 쓰지 않는(잠긴) 상태가 되면 다시 시작해서 적용한다.
let updater = null;
function startUpdater() {
  updater = createUpdater({ dataDir: DATA_DIR, currentVersion: CODE_VERSION, updateUrl: cfg?.updateUrl });
  const run = async () => { if (gate.busy) return; await updater.check(); applyUpdateIfIdle(); };
  setInterval(run, 10 * 60 * 1000);
  setInterval(applyUpdateIfIdle, 60_000);
  runGate(); // 켜지자마자 확인
}
function setGate(s) {
  Object.assign(gate, { pct: 0 }, s);
  sendAll('gate', { ...gate });
}

const GATE_TIMEOUT = 3 * 60 * 1000; // 서버가 느리거나 끊겨도 3분 넘게 붙잡지 않는다
async function runGate() {
  if (!updater || gate.busy || !cfg) return;
  gate.busy = true; setGate({ phase: 'checking' }); render(); pushSeat();
  let timer;
  const timeout = new Promise((r) => { timer = setTimeout(() => r('timeout'), GATE_TIMEOUT); });
  const result = await Promise.race([updater.check((s) => setGate(s)), timeout]);
  clearTimeout(timer);
  if (result && result !== 'timeout' && updater.ready) {
    setGate({ phase: 'applying', version: updater.ready });
    await new Promise((r) => setTimeout(r, 1500)); // 안내를 잠깐 보여 준다
    return applyUpdateIfIdle(true);
  }
  if (result === 'timeout') setGate({ phase: 'error' });
  else if (gate.phase !== 'error') setGate({ phase: 'latest' });
  gate.busy = false;
  render(); pushSeat();
}
async function applyUpdateIfIdle(force = false) {
  if (!updater?.ready || !isLocked() || (!force && ((alive(panelWin) && panelWin.isVisible()) || adminWin || gate.busy))) return;
  console.log('업데이트 적용을 위해 다시 시작합니다:', updater.ready);
  allowQuit('update');
  saveState();
  try { if (st.connected) await sb.from('seats').update({ remaining_sec: st.remainingSec }).eq('id', cfg.seatId); } catch {}
  app.relaunch();
  app.exit(0);
}
// 30초 동안 문제없이 실행되면 "정상 시작"으로 기록 (실패가 반복되면 boot.js가 이전 버전으로 되돌린다)
setTimeout(() => { try { fs.rmSync(path.join(DATA_DIR, 'update', 'boot.json'), { force: true }); } catch {} }, 30_000);

// ---------- 시작 ----------
function startMain() {
  usage.setSeat(cfg.seatId, st.seatName || cfg.seatName);
  if (!appWatch) appWatch = createAppWatcher(console.log);
  createLockWindows();
  createWidget();
  render();
  connect();
  screen.on('display-added', () => { createLockWindows(); render(); });
  screen.on('display-removed', () => { createLockWindows(); placeWidget(); placeAngel(); render(); });
  screen.on('display-metrics-changed', () => { placeWidget(); placeAngel(); });
}

app.whenReady().then(() => {
  if (app.isPackaged && process.platform === 'win32') app.setLoginItemSettings({ openAtLogin: true });
  if (app.isPackaged && process.platform === 'win32') setupFastStart(console.log);
  globalShortcut.register('Control+Alt+Shift+F12', () => openAdmin(cfg ? 'admin' : 'setup'));
  // Windows 종료/로그오프 시에는 막지 않는다
  powerMonitor.on('shutdown', () => { allowQuit('shutdown'); resetForPowerOff('shutdown'); });
  // 절전에 들어가면 꺼진 것으로 기록하고, 깨어나면 다시 켜진 것으로 기록
  powerMonitor.on('suspend', () => { usage.powerOff('sleep'); });
  powerMonitor.on('resume', () => { usage.powerOn(); });
  cfg = loadConfig();
  if (!cfg) openAdmin('setup');
  else {
    startMain(); startWatchdog();
    startGuard();
  }
  startUpdater();
});
app.on('second-instance', () => { if (!cfg) openAdmin('setup'); });
app.on('window-all-closed', (e) => { if (!quitting) e.preventDefault?.(); });
app.on('before-quit', (e) => { if (!quitting) e.preventDefault(); });
app.on('will-quit', () => globalShortcut.unregisterAll());

