files.updater.js:
// 자동 업데이트: 관리자 웹앱 주소의 guest-update/ 에서 새 버전을 확인하고 받아 둔다.
// 손님이 쓰지 않는(잠긴) 상태일 때 프로그램을 다시 시작해서 적용한다.
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

const DEFAULT_URL = 'https://geojebow.github.io/pcbang-admin/guest-update';

function newer(a, b) {
  const x = String(a).split('.').map(Number), y = String(b).split('.').map(Number);
  for (let i = 0; i < 3; i++) if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) > (y[i] || 0);
  return false;
}

function createUpdater({ dataDir, currentVersion, updateUrl, log = console.log }) {
  const base = (updateUrl || DEFAULT_URL).replace(/\/+$/, '');
  const updRoot = path.join(dataDir, 'update');
  let ready = null; // 받아 둔 새 버전

  // onStatus({ phase, pct }) 로 진행 상황을 알린다: checking → downloading(%) → installing → ready / latest / error
  async function check(onStatus = () => {}) {
    try {
      onStatus({ phase: 'checking' });
      const res = await fetch(`${base}/version.json?t=${Date.now()}`, { cache: 'no-store' });
      if (!res.ok) { onStatus({ phase: 'error' }); return null; }
      const info = await res.json();
      let bad = null;
      try { bad = fs.readFileSync(path.join(updRoot, 'bad-version'), 'utf8').trim(); } catch {}
      if (!info.version || !newer(info.version, currentVersion) || info.version === bad) { onStatus({ phase: 'latest' }); return null; }
      if (ready === info.version) { onStatus({ phase: 'ready', version: ready }); return ready; }

      onStatus({ phase: 'downloading', pct: 0, version: info.version });
      const bres = await fetch(`${base}/${info.bundle}?t=${Date.now()}`, { cache: 'no-store' });
      if (!bres.ok) { onStatus({ phase: 'error' }); return null; }
      // 조금씩 받으면서 몇 % 받았는지 알린다
      const total = Number(info.size) || 0;
      const chunks = [];
      let got = 0, lastPct = -1;
      const reader = bres.body.getReader();
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(Buffer.from(value)); got += value.length;
        const pct = total ? Math.min(99, Math.floor((got / total) * 100)) : 0;
        if (pct !== lastPct) { lastPct = pct; onStatus({ phase: 'downloading', pct, version: info.version }); }
      }
      const text = Buffer.concat(chunks).toString('utf8');
      onStatus({ phase: 'installing', pct: 100, version: info.version });
      const hash = crypto.createHash('sha256').update(text).digest('hex');
      if (hash !== info.sha256) { log('업데이트 파일 검증 실패'); onStatus({ phase: 'error' }); return null; }
      const bundle = JSON.parse(text);

      // 임시 폴더에 다 쓴 다음 한 번에 바꾼다
      const staging = path.join(updRoot, 'staging');
      fs.rmSync(staging, { recursive: true, force: true });
      fs.mkdirSync(staging, { recursive: true });
      for (const [name, content] of Object.entries(bundle.files)) {
        if (name.includes('..') || path.isAbsolute(name)) continue;
        const file = path.join(staging, name);
        fs.mkdirSync(path.dirname(file), { recursive: true });
        fs.writeFileSync(file, content);
      }
      fs.writeFileSync(path.join(staging, 'version.json'), JSON.stringify({ version: info.version, date: info.date || null }));
      const current = path.join(updRoot, 'current');
      const old = path.join(updRoot, 'old');
      fs.rmSync(old, { recursive: true, force: true });
      if (fs.existsSync(current)) fs.renameSync(current, old);
      fs.renameSync(staging, current);
      fs.rmSync(old, { recursive: true, force: true });
      ready = info.version;
      log(`새 버전 ${info.version} 준비됨`);
      onStatus({ phase: 'ready', version: ready });
      return ready;
    } catch (e) {
      log('업데이트 확인 실패: ' + e.message);
      onStatus({ phase: 'error' });
      return null;
    }
  }
  return { check, get ready() { return ready; } };
}

module.exports = { createUpdater };

files.usage.js:
// PC 사용 기록
// - 전원 기록(power_log): PC가 켜진 시각 ~ 꺼진 시각 (절전도 꺼짐으로 본다)
// - 사용 기록(use_sessions): 잠금이 풀린 순간 ~ 다시 잠긴 순간. 실제로 사용한 초를 1초씩 센다.
//   (1시간을 받아도 40분 쓰고 PC를 끄면 40분으로 기록된다)
// - 프로그램별 사용 시간: 사용 중 1초마다 맨 앞 프로그램에 1초씩 더한다.
// 기록은 이 PC의 usage.json 에 먼저 저장하고 1분마다 Supabase에 올린다. 인터넷이 끊겨도 나중에 올라간다.
const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');

const OFF_GAP_MS = 3 * 60 * 1000;   // main.js 와 같은 기준: 3분 넘게 꺼져 있었으면 PC가 꺼졌던 것
const KEEP_LOCAL = 40;              // 이 PC에 남겨 두는 지난 기록 수 (인터넷이 없어도 손님 화면에 보이게)
const MAX_APPS = 40;

function createUsage({ dataDir, log = () => {}, lostKind = 'lost' }) {
  const FILE = path.join(dataDir, 'usage.json');
  let d = {};
  try { d = JSON.parse(fs.readFileSync(FILE, 'utf8')) || {}; } catch {}
  d.queue = Array.isArray(d.queue) ? d.queue : [];          // 아직 서버에 못 올린 끝난 기록 [{ t, row }]
  d.recent = Array.isArray(d.recent) ? d.recent : [];       // 끝난 사용 기록 (최근 것부터)
  d.recentPower = Array.isArray(d.recentPower) ? d.recentPower : [];

  let seat = { id: null, name: '' };
  let reasonHint = null;      // 다음에 잠길 때 남길 이유
  let dirty = true;
  let sb = null;
  let halted = false;         // PC를 끄는 중/절전 중에는 새 기록을 시작하지 않는다

  const now = () => new Date().toISOString();
  const gap = d.savedAt ? Date.now() - d.savedAt : Infinity;
  const resumable = gap <= OFF_GAP_MS && lostKind !== 'forced'; // 강제 종료로 꺼졌으면 이어 가지 않는다

  // ---------- 시작할 때: 지난 기록 마무리 ----------
  // lostKind: 강제 종료 감시가 PC를 껐으면 'forced', 아니면 'lost'(전원 등)
  if (d.session && !resumable) finishSession(lostKind, d.session.lastSeen);
  if (d.power && (d.power.offAt || !resumable)) finishPower(d.power.offKind || lostKind, d.power.offAt || d.power.lastSeen);
  if (!d.power) startPower(true);

  function save() {
    d.savedAt = Date.now();
    try { fs.writeFileSync(FILE, JSON.stringify(d)); dirty = false; } catch {}
  }
  setInterval(() => { if (dirty || d.session || d.power) save(); }, 10_000);

  function enqueue(t, row) {
    d.queue = d.queue.filter((q) => !(q.t === t && q.row.id === row.id));
    d.queue.push({ t, row });
    if (d.queue.length > 300) d.queue = d.queue.slice(-300);
  }

  // ---------- 전원 ----------
  function startPower(atBoot) {
    // Windows가 막 켜졌으면(10분 이내) 실제 부팅 시각, 아니면 지금(로그인/절전 해제 시각)
    const up = os.uptime() * 1000;
    const onAt = atBoot && up < 10 * 60 * 1000 ? new Date(Date.now() - up).toISOString() : now();
    d.power = { id: crypto.randomUUID(), onAt, lastSeen: now(), offAt: null, offKind: null };
    dirty = true;
  }
  function powerRow(p) {
    return { id: p.id, seat_id: p.seatId || seat.id, seat_name: p.seatName || seat.name, on_at: p.onAt, last_seen: p.offAt || p.lastSeen, off_at: p.offAt, off_kind: p.offKind };
  }
  function finishPower(kind, at) {
    const p = d.power; if (!p) return;
    p.offAt = p.offAt || at || now(); p.offKind = p.offKind || kind;
    if (p.seatId || seat.id) {
      enqueue('power_log', powerRow(p));
      d.recentPower = [powerRow(p), ...d.recentPower.filter((x) => x.id !== p.id)].slice(0, KEEP_LOCAL);
    }
    d.power = null; dirty = true;
  }

  // ---------- 사용 ----------
  function startSession(mode, remainingSec) {
    d.session = {
      id: crypto.randomUUID(), seatId: seat.id, seatName: seat.name, mode,
      startedAt: now(), lastSeen: now(), usedSec: 0,
      grantedSec: mode === 'timed' ? remainingSec : null, apps: {},
    };
    reasonHint = null; dirty = true;
  }
  function sessionRow(s, ended) {
    return {
      id: s.id, seat_id: s.seatId || seat.id, seat_name: s.seatName || seat.name, mode: s.mode,
      started_at: s.startedAt, ended_at: ended ? s.endedAt : null, last_seen: s.endedAt || s.lastSeen,
      used_sec: s.usedSec, granted_sec: s.grantedSec, end_reason: ended ? s.endReason : null, apps: s.apps,
    };
  }
  function finishSession(reason, at) {
    const s = d.session; if (!s) return;
    s.endedAt = at || now(); s.endReason = reason || 'lock';
    if (s.seatId || seat.id) {
      const row = sessionRow(s, true);
      enqueue('use_sessions', row);
      d.recent = [row, ...d.recent.filter((x) => x.id !== s.id)].slice(0, KEEP_LOCAL);
    }
    d.session = null; reasonHint = null; dirty = true;
    flush();
  }

  // 1초마다 호출: using = 지금 잠금이 풀려 사용 중인지
  function tick({ using, mode, remainingSec, app }) {
    if (!seat.id || halted) return;
    const t = now();
    if (d.power) { d.power.lastSeen = t; d.power.seatId = d.power.seatId || seat.id; d.power.seatName = seat.name; }
    else startPower(false);
    if (using && !d.session) startSession(mode, remainingSec);
    if (!using && d.session) return finishSession(reasonHint || 'lock');
    const s = d.session; if (!s) return;
    s.usedSec += 1; s.lastSeen = t;
    if (mode === 'free') { s.mode = 'free'; s.grantedSec = null; }
    if (app) {
      if (!(app in s.apps) && Object.keys(s.apps).length >= MAX_APPS) app = '기타';
      s.apps[app] = (s.apps[app] || 0) + 1;
    }
  }

  // 사용 중 시간이 충전/조정되면 받은 시간에 반영 (delta 초)
  function granted(deltaSec) {
    const s = d.session;
    if (s && s.grantedSec != null && deltaSec) { s.grantedSec = Math.max(s.usedSec, s.grantedSec + deltaSec); dirty = true; }
  }

  // PC 끄기 / 재시작 / 절전: 사용 기록과 전원 기록을 바로 닫는다
  function powerOff(kind) {
    halted = true;
    finishSession(kind === 'sleep' ? 'sleep' : kind === 'quit' ? 'quit' : 'power');
    finishPower(kind);
    save();
    return Promise.race([flush(), new Promise((r) => setTimeout(r, 2500))]);
  }
  function powerOn() { halted = false; if (!d.power) { startPower(false); save(); flush(); } }

  // ---------- 서버로 올리기 ----------
  let flushing = null;
  let lastError = null;
  function flush() {
    if (!sb || !seat.id) return Promise.resolve();
    if (flushing) return flushing;
    flushing = (async () => {
      try {
        const sends = [...d.queue];
        if (d.power) sends.push({ t: 'power_log', row: powerRow(d.power), live: true });
        if (d.session) sends.push({ t: 'use_sessions', row: sessionRow(d.session, false), live: true });
        for (const t of ['power_log', 'use_sessions']) {
          const items = sends.filter((x) => x.t === t);
          if (!items.length) continue;
          const rows = items.map((x) => x.row).filter((r) => r.seat_id);
          const { error } = await sb.from(t).upsert(rows, { onConflict: 'id' });
          if (error) { lastError = error.message; continue; }
          lastError = null;
          const sent = new Set(items.filter((x) => !x.live).map((x) => x.row.id));
          d.queue = d.queue.filter((q) => !(q.t === t && sent.has(q.row.id)));
          dirty = true;
        }
      } catch (e) { lastError = e.message; }
      flushing = null;
    })();
    return flushing;
  }
  setInterval(flush, 60_000);

  return {
    setClient(client) { sb = client; flush(); },
    setSeat(id, name) {
      seat = { id, name: name || '' };
      if (d.session && !d.session.seatId) d.session.seatId = id;
      if (d.session) d.session.seatName = seat.name;
    },
    tick, granted, powerOff, powerOn, flush,
    hint(reason) { if (d.session) reasonHint = reason; },
    active: () => !!d.session,
    // 손님 화면용: 지금 사용 중인 기록 + 바로 전 기록
    live() {
      const s = d.session;
      return {
        current: s ? { startedAt: s.startedAt, usedSec: s.usedSec, grantedSec: s.grantedSec, mode: s.mode, apps: s.apps } : null,
        last: d.recent[0] || null,
        powerOnAt: d.power?.onAt || null,
      };
    },
    // 손님 화면 '사용 기록' 탭: 서버 기록에 이 PC에만 있는 기록을 합친다
    async history(days = 7) {
      const since = new Date(Date.now() - days * 86400_000).toISOString();
      let sessions = [], powers = [], error = null;
      if (sb && seat.id) {
        const [a, b] = await Promise.all([
          sb.from('use_sessions').select('*').eq('seat_id', seat.id).gte('started_at', since).order('started_at', { ascending: false }).limit(300),
          sb.from('power_log').select('*').eq('seat_id', seat.id).gte('on_at', since).order('on_at', { ascending: false }).limit(300),
        ]);
        error = a.error?.message || b.error?.message || null;
        sessions = a.data || []; powers = b.data || [];
      }
      const merge = (list, local, key) => {
        const m = new Map(list.map((x) => [x.id, x]));
        for (const x of local) if (x && x[key] >= since) m.set(x.id, x);
        return [...m.values()].sort((x, y) => (x[key] < y[key] ? 1 : -1));
      };
      sessions = merge(sessions, [...d.recent, d.session && sessionRow(d.session, false)], 'started_at');
      powers = merge(powers, [...d.recentPower, d.power && powerRow(d.power)], 'on_at');
      return { sessions, powers, error, liveId: d.session?.id || null, powerId: d.power?.id || null };
    },
    lastError: () => lastError,
  };
}

module.exports = { createUsage };

